<?php
require_once "../config/app.php"; require_login();
$page_title="Prescriptions";
if($_SERVER["REQUEST_METHOD"]==="POST"){verify_csrf();$customer=(int)($_POST["customer_id"]??0);$date=$_POST["prescription_date"]??date("Y-m-d");$notes=trim($_POST["notes"]??"");$status=$_POST["status"]??"pending";
 if($customer>0&&in_array($status,["pending","verified","dispensed","rejected"],true)){$st=$conn->prepare("INSERT INTO prescriptions(customer_id,pharmacist_id,prescription_date,notes,status) VALUES(?,?,?,?,?)");$st->bind_param("iisss",$customer,$_SESSION["user_id"],$date,$notes,$status);$st->execute();flash("success","Prescription record saved. Ensure a licensed pharmacist verifies it before dispensing.");}else{flash("danger","Select a customer.");}header("Location: index.php");exit;}
$customers=$conn->query("SELECT id,fullname FROM customers ORDER BY fullname");
$rows=$conn->query("SELECT p.*,c.fullname,u.fullname pharmacist FROM prescriptions p JOIN customers c ON c.id=p.customer_id JOIN users u ON u.id=p.pharmacist_id ORDER BY p.id DESC");
require "../includes/header.php";
?>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-header">Add prescription record</div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="mb-3"><label class="form-label">Customer</label><select class="form-select" name="customer_id" required><option value="">Select customer</option><?php while($c=$customers->fetch_assoc()): ?><option value="<?= (int)$c["id"] ?>"><?= e($c["fullname"]) ?></option><?php endwhile; ?></select></div><div class="mb-3"><label class="form-label">Prescription date</label><input type="date" class="form-control" name="prescription_date" value="<?= date("Y-m-d") ?>" required></div><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="pending">Pending verification</option><option value="verified">Verified</option><option value="dispensed">Dispensed</option><option value="rejected">Rejected</option></select></div><div class="mb-3"><label class="form-label">Notes / reference</label><textarea class="form-control" name="notes"></textarea></div><button class="btn btn-primary">Save record</button></form></div></div></div>
<div class="col-lg-8"><div class="card"><div class="card-header">Prescription records</div><div class="card-body table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Date</th><th>Pharmacist</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php if(!$rows->num_rows): ?><tr><td colspan="5">No prescriptions recorded.</td></tr><?php endif; ?><?php while($p=$rows->fetch_assoc()): ?><tr><td><?= e($p["fullname"]) ?></td><td><?= e($p["prescription_date"]) ?></td><td><?= e($p["pharmacist"]) ?></td><td><span class="badge badge-soft"><?= e($p["status"]) ?></span></td><td><?= e($p["notes"]) ?></td></tr><?php endwhile; ?></tbody></table></div></div></div></div>
